# Measured only; retain the full original release policy.
from .bridge.army_query_timing import start_army_timing, finish_army_timing
_plan_release_formal_untimed = plan_release_formal
def plan_release_formal(*args, **kwargs):
    timer = start_army_timing("service.prisoner_release_plan")
    try:
        return _plan_release_formal_untimed(*args, **kwargs)
    finally:
        finish_army_timing(timer, step="plan-release")
